import json, sys, os
W = "/Users/kristinarash/Library/Caches/sportsci-batch-97"
inp = json.load(open(os.path.join(W, "inputs.json"), encoding="utf-8"))
items = inp if isinstance(inp, list) else inp.get("papers", list(inp.values()))
src = {i["id"]: i["sourceFile"] for i in items if isinstance(i, dict) and "id" in i}
tax = json.load(open(os.path.join(W, "taxonomy.json"), encoding="utf-8"))
for n in range(1, 9):
    pid = "Q0%d" % n
    p = os.path.join(W, "verified", pid + ".json")
    raw = open(p, encoding="utf-8").read()
    d = json.loads(raw)
    fixed = d["sourceFile"] != src[pid]
    d["sourceFile"] = src[pid]
    probs = []
    if "—" in raw: probs.append("em dash")
    if d["decision"] != "EXCLUDE":
        if d["studyDesign"] not in tax["studyDesigns"]: probs.append("design")
        if d["primaryDomain"] not in d["domains"]: probs.append("primary not in domains")
        for k, t in [("domains","domains"),("audiences","audiences"),("sports","sports"),("populations","populations")]:
            for v in d[k]:
                if v not in tax[t]: probs.append("%s:%s" % (k, v))
    with open(p, "w", encoding="utf-8") as f:
        json.dump(d, f, ensure_ascii=False, indent=1)
        f.write("\n")
    print(pid, "sourceFile fixed" if fixed else "sourceFile ok", d["verification"]["status"], d["verification"]["spotCheckPriority"], probs)

